        AWT_TO_JAGEX.put(KeyEvent.VK_ENTER, KeyCode.KC_ENTER);
        AWT_TO_JAGEX.put(KeyEvent.VK_TAB, KeyCode.KC_TAB);
        AWT_TO_JAGEX.put(KeyEvent.VK_ESCAPE, KeyCode.KC_ESCAPE);
